    enonce: "<span class=\"q\">1) </span>أنشر ثمّ اختصر: <span dir=\"ltr\" class=\"expr\">E = (-x + 6)(<span class=\"frac\"><span class=\"num\">3</span><span class=\"den\">2</span></span>x - 3) - (-x + 6)</span><br><span class=\"q\">2) </span>أنشر ثمّ اختصر: احسب <span dir=\"ltr\" class=\"expr\">E</span> إذا كان <span dir=\"ltr\" class=\"expr\">x = -<span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">2</span></span></span> حيث <span dir=\"ltr\" class=\"expr\">E = -<span class=\"frac\"><span class=\"num\">3</span><span class=\"den\">2</span></span>x<sup>2</sup> + 13x - 24</span><br><span class=\"q\">3) </span>أنشر ثمّ اختصر: احسب <span dir=\"ltr\" class=\"expr\">E</span> إذا كان <span dir=\"ltr\" class=\"expr\">x = -<span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">2</span></span></span> حيث فكّك إلى جداء عوامل: <span dir=\"ltr\" class=\"expr\">E = (-x + 6)(<span class=\"frac\"><span class=\"num\">3</span><span class=\"den\">2</span></span>x - 3) - (-x + 6)</span><br><span class=\"q\">4) </span>أنشر ثمّ اختصر: احسب <span dir=\"ltr\" class=\"expr\">E</span> إذا كان <span dir=\"ltr\" class=\"expr\">x = -<span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">2</span></span></span> حيث فكّك إلى جداء عوامل: جد العدد الكسري النسبي x بحيث: <span dir=\"ltr\" class=\"expr\">E = 0</span> <span dir=\"ltr\" class=\"expr\">E = (-x + 6)(<span class=\"frac\"><span class=\"num\">3</span><span class=\"den\">2</span></span>x - 4)</span>",
    correction: [{"quoi":"","math":"<b>1)</b>"},{"quoi":"القاعدة","math":"جداء قوسين يعطي أربعة جداءات"},{"quoi":"ننشر","math":"<span dir=\"ltr\" class=\"expr\">(-x + 6)(<span class=\"frac\"><span class=\"num\">3</span><span class=\"den\">2</span></span>x - 3) - (-x + 6) = (-x + 6) × [<span class=\"frac\"><span class=\"num\">3</span><span class=\"den\">2</span></span>x - 4]</span>"},{"quoi":"نضرب القوسين","math":"<span dir=\"ltr\" class=\"expr\">(-x + 6)(<span class=\"frac\"><span class=\"num\">3</span><span class=\"den\">2</span></span>x - 4) = -<span class=\"frac\"><span class=\"num\">3</span><span class=\"den\">2</span></span>x<sup>2</sup> + 13x - 24</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">E = -<span class=\"frac\"><span class=\"num\">3</span><span class=\"den\">2</span></span>x<sup>2</sup> + 13x - 24</span>"},{"quoi":"","math":"<b>2)</b>"},{"quoi":"نعوّض في الشكل المنشور","math":"<span dir=\"ltr\" class=\"expr\">E = -<span class=\"frac\"><span class=\"num\">3</span><span class=\"den\">2</span></span>(-<span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">2</span></span>)<sup>2</sup> + 13(-<span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">2</span></span>) - 24</span>"},{"quoi":"نحسب","math":"<span dir=\"ltr\" class=\"expr\">E = -<span class=\"frac\"><span class=\"num\">247</span><span class=\"den\">8</span></span></span>"},{"quoi":"نتحقّق بالشكل المفكّك","math":"<span dir=\"ltr\" class=\"expr\">(-(-<span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">2</span></span>) + 6)(<span class=\"frac\"><span class=\"num\">3</span><span class=\"den\">2</span></span>(-<span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">2</span></span>) - 4) = -<span class=\"frac\"><span class=\"num\">247</span><span class=\"den\">8</span></span></span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">E = -<span class=\"frac\"><span class=\"num\">247</span><span class=\"den\">8</span></span></span>"},{"quoi":"","math":"<b>3)</b>"},{"quoi":"نلاحظ العامل المشترك","math":"القوس <span dir=\"ltr\" class=\"expr\">(-x + 6)</span> موجود في الحدّين"},{"quoi":"نجمع ما تبقّى","math":"ما تبقّى<span dir=\"ltr\" class=\"expr\">: <span class=\"frac\"><span class=\"num\">3</span><span class=\"den\">2</span></span>x - 4</span>"},{"quoi":"نكتب الجداء","math":"<span dir=\"ltr\" class=\"expr\">E = (-x + 6)(<span class=\"frac\"><span class=\"num\">3</span><span class=\"den\">2</span></span>x - 4)</span>"},{"quoi":"نتحقّق بالنشر","math":"<span dir=\"ltr\" class=\"expr\">(-x + 6)(<span class=\"frac\"><span class=\"num\">3</span><span class=\"den\">2</span></span>x - 4) = (-x + 6)(<span class=\"frac\"><span class=\"num\">3</span><span class=\"den\">2</span></span>x - 3) - (-x + 6)</span>"},{"quoi":"","math":"<b>4)</b>"},{"quoi":"نستعمل الشكل المفكّك","math":"<span dir=\"ltr\" class=\"expr\">E = (-x + 6)(<span class=\"frac\"><span class=\"num\">3</span><span class=\"den\">2</span></span>x - 4)</span>"},{"quoi":"القاعدة","math":"جداء منعدم يعني أنّ أحد عامليه منعدم على الأقلّ"},{"quoi":"نكتب الحالتين","math":"<span dir=\"ltr\" class=\"expr\">-x + 6 = 0</span>  أو  <span dir=\"ltr\" class=\"expr\"><span class=\"frac\"><span class=\"num\">3</span><span class=\"den\">2</span></span>x - 4 = 0</span>"},{"quoi":"الحلّ الأول","math":"<span dir=\"ltr\" class=\"expr\">x = 6</span>"},{"quoi":"الحلّ الثاني","math":"<span dir=\"ltr\" class=\"expr\">x = <span class=\"frac\"><span class=\"num\">8</span><span class=\"den\">3</span></span></span>"},{"quoi":"النتيجة","math":"للمعادلة حلاّن: 6 و <span dir=\"ltr\" class=\"expr\"><span class=\"frac\"><span class=\"num\">8</span><span class=\"den\">3</span></span></span>"}],
